#include <Adafruit_NeoPixel.h>
#define PIR_PIN D3
#define LDR_PIN D1  // A0 equivalent = GPIO3, analog read
#define BTN_PIN D2
#define LED_PIN D10
#define NUM_LEDS 4
Adafruit_NeoPixel strip(NUM_LEDS, LED_PIN, NEO_GRB + NEO_KHZ800);
int mode = 0; // 0 auto, 1 always on, 2 off
unsigned long lightUntil = 0;
unsigned long lastBtn = 0;
bool lastPir = false;
void setup(){
  pinMode(PIR_PIN, INPUT);
  pinMode(BTN_PIN, INPUT_PULLUP);
  pinMode(LDR_PIN, INPUT);
  strip.begin(); strip.clear(); strip.show(); strip.setBrightness(80);
}
bool isDark(){
  int v = analogRead(LDR_PIN); // photoresistor divider: low light -> high resistance -> low voltage? depending wiring; calibrate threshold
  // GL5516 +10k to GND: bright -> resistance ~5k -> voltage ~1.1V -> ADC ~ 1400; dark -> 200k -> ~3.1V -> ~3800
  // So dark = high value
  return v > 2000; // threshold adjustable
}
void loop(){
  // button with debounce
  if(digitalRead(BTN_PIN)==LOW && millis()-lastBtn>500){
    lastBtn=millis();
    mode=(mode+1)%3;
    // brief feedback: blink
    strip.fill(strip.Color(0,50,0)); strip.show(); delay(150);
  }
  bool pir = digitalRead(PIR_PIN);
  unsigned long now = millis();
  if(mode==0){
    if(pir && isDark()){
      lightUntil = now + 30000; // 30 sec
    }
    if(now < lightUntil){
      // warm white
      strip.fill(strip.Color(255,140,40));
      strip.show();
    } else {
      // fade out
      strip.clear(); strip.show();
    }
  } else if(mode==1){
    strip.fill(strip.Color(255,140,40)); strip.show();
  } else {
    strip.clear(); strip.show();
  }
  delay(50);
}
